def inr_format(amount):
    # Remove any leading zeros, as per the test examples
    amount = str(amount).lstrip('0')
    if amount:
        # Split into groups of 3 and 2, then format with commas
        groups = [amount[i:i+3] for i in range(0, len(amount), 3)]
        groups = [group + ',' + group for group in groups]
        return ','.join(groups)

